// Tone Zone originals added in v0.4.0: 70 pedals of our own design (drives, fuzz, boosts, dynamics, EQ, filters,
// modulation, pitch, delays, reverbs, synths, loopers, utilities, glitch and ambient boxes).
// Enclosures: gfx/forms-tz6.js (form 'tz6', look picked by `art`).
import { K, SEL, TOG, FOOT, LED, SLIDER, SCREEN, TREADLE, db } from './helpers.js';
import { TZ } from './builders.js';

const IO = { ins: ['INPUT'], outs: ['OUTPUT'] };
const O = (o) => TZ(Object.assign({ noStd: true, form: 'tz6', ports: IO }, o));
const dbK = (p, label, o = {}) => K(p, label, Object.assign({ min: -24, max: 12, def: 0, display: db }, o));
const pctOf = (v) => Math.round(v * 100) + '%';
const sgn = (v) => (v > 0 ? '+' : '') + Math.round(v);
const msK = (p, label, min, max, def, o = {}) => K(p, label, Object.assign({ min, max, def, curve: 'log', display: (v) => (v >= 1000 ? (v / 1000).toFixed(2) + ' s' : Math.round(v) + ' ms') }, o));
const hz = (v) => (v >= 1000 ? (v / 1000).toFixed(1) + ' kHz' : Math.round(v) + ' Hz');
const sec = (v) => (v < 1 ? Math.round(v * 1000) + ' ms' : v.toFixed(2) + ' s');
const forever = (v) => (v >= 0.999 ? 'FOREVER' : pctOf(v));
const STD = (color = '#ff2a1a', label) => [FOOT(label ? { label } : {}), LED({ color })];
const TAP = (color = '#ff2a1a') => [FOOT({ action: 'tap', label: 'TAP' }), FOOT({ label: 'ON' }), LED({ bind: 'tap:time', color }), LED({ color })];

